//! Python warpsign's fix dylib injection, against `fixtures/warpsign_fix.json`
//! (generated by `tools/gen_fixtures.py`, which runs Python warpsign's own
//! code through LIEF on byte-built binaries). The fix dylibs themselves are
//! stand-ins here: ours are built from `ios/WarpsignFix`, not Python's.

use std::path::{Path, PathBuf};

use base64::Engine;
use serde_json::{Value as Json, json};
use sha2::{Digest, Sha256};
use warpsign_core::bundle_mapping::BundleMapping;
use warpsign_core::macho_edit;
use warpsign_core::warpsign_fix::{self, FixOptions};

fn fixture() -> Json {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/warpsign_fix.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn str_of(value: &Json) -> &str {
    value.as_str().unwrap()
}

fn strings(value: &Json) -> Vec<String> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| str_of(v).to_string())
        .collect()
}

#[test]
fn dylib_paths_match() {
    for case in fixture()["dylib_paths"].as_array().unwrap() {
        let executable = str_of(&case["executable"]);
        assert_eq!(
            warpsign_fix::dylib_path(Path::new(executable), str_of(&case["name"])),
            str_of(&case["expected"]),
            "{executable}"
        );
    }
}

#[test]
fn remappings_json_matches() {
    for case in fixture()["remappings"].as_array().unwrap() {
        let name = str_of(&case["name"]);
        // The mapping as Python's _sign_components finds it: bundle IDs
        // mapped and resources collected, no entitlements mapped yet
        let mut mapping = BundleMapping::new(
            strings(&case["original_team_ids"]),
            str_of(&case["new_team_id"]),
            str_of(&case["main_bundle_id"]),
            case["randomize"].as_bool().unwrap(),
        );
        mapping.force_original_id = case["force_original_id"].as_bool().unwrap();
        mapping.profile_type = str_of(&case["profile_type"]).parse().unwrap();
        for component in case["components"].as_array().unwrap() {
            mapping.map_bundle_id(str_of(&component["bundle_id"]));
            let entitlements: plist::Value =
                serde_json::from_value(component["entitlements"].clone()).unwrap();
            mapping.extract_resources_from_entitlements(entitlements.as_dictionary().unwrap());
        }
        assert_eq!(
            warpsign_fix::remappings_json(&mapping).as_deref(),
            case["expected"].as_str(),
            "{name}"
        );
    }
}

fn sha256_hex(data: &[u8]) -> String {
    Sha256::digest(data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// A folder of stand-in fix dylibs, as WarpSign's FixDylibs/
fn stand_in_dylibs(dir: &Path) {
    for name in warpsign_fix::KNOWN_DYLIBS {
        std::fs::write(dir.join(name), format!("stand-in {name}")).unwrap();
    }
}

fn files_under(root: &Path) -> Vec<String> {
    fn walk(root: &Path, dir: &Path, found: &mut Vec<String>) {
        for entry in std::fs::read_dir(dir).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(root, &path, found);
            } else {
                found.push(warpsign_core::inspect::slash_path(
                    path.strip_prefix(root).unwrap(),
                ));
            }
        }
    }
    let mut found = Vec::new();
    walk(root, root, &mut found);
    found.sort();
    found
}

/// Every dylib command per slice, in the fixture's form
fn dylib_commands(path: &Path) -> Json {
    let version = |v: u32| json!([v >> 16, (v >> 8) & 0xff, v & 0xff]);
    let data = std::fs::read(path).unwrap();
    let slices: Vec<Json> = macho_edit::dylib_commands(&data)
        .unwrap()
        .into_iter()
        .map(|commands| {
            commands
                .into_iter()
                .map(|(cmd, dylib)| {
                    json!({
                        "cmd": cmd,
                        "path": dylib.path,
                        "timestamp": dylib.timestamp,
                        "current_version": version(dylib.current_version),
                        "compatibility_version": version(dylib.compatibility_version),
                    })
                })
                .collect()
        })
        .collect();
    json!(slices)
}

#[test]
fn injection_matches() {
    let base64 = base64::engine::general_purpose::STANDARD;
    for case in fixture()["injections"].as_array().unwrap() {
        let name = str_of(&case["name"]);
        let expected = &case["expected"];
        let options = FixOptions {
            inject_warpsign_fix: case["inject_warpsign_fix"].as_bool().unwrap(),
            hide_home_indicator: case["hide_home_indicator"].as_bool().unwrap(),
        };

        let tmp = tempfile::tempdir().unwrap();
        let dylibs = tmp.path().join("FixDylibs");
        std::fs::create_dir(&dylibs).unwrap();
        stand_in_dylibs(&dylibs);
        let app: PathBuf = tmp.path().join("Payload").join("App.app");
        let inputs = case["files"].as_object().unwrap();
        for (relative, data) in inputs {
            let path = app.join(relative);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, base64.decode(str_of(data)).unwrap()).unwrap();
        }

        warpsign_fix::stage(&app, options, Some(&dylibs), &mut |_| {}).unwrap();
        // As the PatchBinaries step does (and _sign_components): the first
        // failure stops the sign
        let mut error = None;
        for component in case["components"].as_array().unwrap() {
            let executable = Path::new(str_of(&component["executable"]));
            if !app.join(executable).exists() {
                continue;
            }
            let is_primary = component["is_primary"].as_bool().unwrap();
            if !is_primary && warpsign_fix::is_known_dylib(executable) {
                continue;
            }
            let is_main = component["is_main"].as_bool().unwrap();
            if let Err(e) =
                warpsign_fix::patch_binary(&app, executable, is_main, options, &mut |_| {})
            {
                error = Some(e.to_string());
                break;
            }
        }

        assert_eq!(
            error.is_some(),
            !expected["error"].is_null(),
            "{name}: error {error:?}, Python: {}",
            expected["error"]
        );
        assert_eq!(
            app.join("Frameworks").is_dir(),
            expected["frameworks_dir"].as_bool().unwrap(),
            "{name}: Frameworks/"
        );
        let files = files_under(&app);
        assert_eq!(files, strings(&expected["files"]), "{name}: files");

        for (relative, commands) in expected["dylib_commands"].as_object().unwrap() {
            if !inputs.contains_key(relative) {
                // Staged: Python's own dylib, which ours needn't match
                continue;
            }
            assert_eq!(
                &dylib_commands(&app.join(relative)),
                commands,
                "{name}: dylib commands of {relative}"
            );
        }
        for (relative, hash) in expected["known_dylib_sha256"].as_object().unwrap() {
            let ours = sha256_hex(&std::fs::read(app.join(relative)).unwrap());
            // Kept from the app where Python kept it, else copied in
            let input = inputs
                .get(relative)
                .map(|data| sha256_hex(&base64.decode(str_of(data)).unwrap()));
            if input.as_deref() == Some(str_of(hash)) {
                assert_eq!(Some(ours), input, "{name}: {relative} kept");
            } else {
                let file = Path::new(relative).file_name().unwrap();
                let stand_in = sha256_hex(&std::fs::read(dylibs.join(file)).unwrap());
                assert_eq!(ours, stand_in, "{name}: {relative} copied in");
            }
        }
    }
}

#[test]
fn needs_the_dylibs_it_injects() {
    let tmp = tempfile::tempdir().unwrap();
    let app = tmp.path().join("App.app");
    std::fs::create_dir(&app).unwrap();
    let options = FixOptions {
        inject_warpsign_fix: false,
        hide_home_indicator: true,
    };
    let error = warpsign_fix::stage(&app, options, None, &mut |_| {}).unwrap_err();
    assert!(error.to_string().contains("ForceHideHomeIndicator.dylib"));
    let empty = tmp.path().join("empty");
    std::fs::create_dir(&empty).unwrap();
    assert!(warpsign_fix::stage(&app, options, Some(&empty), &mut |_| {}).is_err());
    // Nothing to inject, nothing needed
    warpsign_fix::stage(&app, FixOptions::default(), None, &mut |_| {}).unwrap();
}
